      }
      const install = installRealAdapter(world, policy, {
        resolveDynamicDecision: (async (input: {
          operation: CanonicalOperation
          staticRules: CanonicalRules | undefined
          staticDefault: 'ask' | 'deny'
        }) => {
          seen.push({ rules: input.staticRules })
          return undefined
        }) as never,
      })
