    : []
  return [
    '---',
    'schemaVersion: 1',
    'blueprintId: A3P4E2-BP',
    'revision: "1"',
    'leader:',
    '  templateId: leader',
    '  persona: You lead the A3P4E2 team.',
    '  capabilities:',
    '    teamTools:',
    '      kind: allow',
    '      items:',
    '        - team_send_message',
