    '    builtinToolDeny: []',
    '    skills:',
    '      kind: allow',
    '      items: []',
    '    mcp:',
    '      kind: allow',
    '      items: []',
    ...(withPermissions
      ? [
          '    permissions:',
          '      default: deny',
          '      allow:',
          '        - tool: write',
          '          resource:',
          '            kind: exact',
          `            path: "${leaderAllowPath}"`,
          '      ask: []',
          '      deny: []',
        ]
      : []),
    'members:',
    '  - templateId: worker',
    '    displayName: Worker',
    '    persona: You do the A3P4E2 work.',
    ...(withPermissions
      ? [
          '    capabilities:',
          '      teamTools:',
          '        kind: allow',
