const ROOT_SID = 'session-root-a3p4prod'
const NOW = '2026-10-05T12:00:00.000Z'
const WORKER_ID = parseInstanceId('inst-a3p4worker')

const BLUEPRINT_SOURCE = [
  '---',
  'schemaVersion: 3',
  'blueprintId: A3P4-BP',
  'revision: "1"',
  'leader:',
  '  templateId: leader',
  '  persona: You lead the A3P4 team.',
  'members:',
  '  - templateId: worker',
  '    displayName: Worker',
  '    persona: You do the A3P4 work.',
  'teamEnvelope:',
  '  allow:',
  '    - send-message',
  '    - report-progress',
  '  deny: []',
  'memberEnvelopes:',
  '  - templateId: worker',
  '    envelope:',
  '      allow:',
  '        - send-message',
  '      deny: []',
  'permissionMutationEnvelope:',
  '  rules: []',
  'teamHardEnvelope:',
  '  rules: []',
  'policyStates:',
  '  - id: default',
  '    description: The A3P4 default state.',
  'quotas:',
  '  team:',
  '    maxInstances: 4',
